const $=(q)=>root.querySelector(q),all=(q)=>[...root.querySelectorAll(q)],rpc=async(name,args={})=>{const {data,error}=await client.rpc(name,args);if(error)throw error;if(['academy_save_content','academy_save_menu','academy_save_content_with_notice','academy_save_menu_with_notice'].includes(name)){deleteDraft('editor',args.p_document.id);deleteDraft('content',args.p_document.id);}return data;};
