function pending(){root.innerHTML=`<div class="shell"><header>${brand()}<button id="logout" class="ghost">Выйти</button></header><main class="card profile-summary"><span class="pill">${s.profile.status==='pending'?'Ждём подтверждения':'Доступ приостановлен'}</span><h1>${s.profile.status==='pending'?'Вы почти в команде':'Обратитесь к администратору'}</h1><p>${esc(s.profile.full_name)}, ${s.profile.status==='pending'?'администратор проверит заявку и откроет обучение.':'администратор поможет восстановить доступ.'}</p><div class="notice">${esc(restaurants[s.profile.restaurant_id]||'')}<br>${esc(departmentLabel())} · ${esc(positionLabel())}</div><button id="refresh" class="primary wide" style="margin-top:20px">Проверить доступ</button>${message()}</main></div>`;$('#logout').onclick=logout;$('#refresh').onclick=()=>act(load);}
